    }

    node->v = v;
}

static void nodeDestruct(struct SaveNode* node) /* <=== nodeDestruct */ 
{
    TR_ASSERT(node != NULL);

    if (node->sorted != NULL)
    {
        tr_free(node->sorted->val.l.vals);
        tr_free(node->sorted);
    }
}

